"use client";

import Link from "next/link";
import { ArrowLeft, Network, Code, Copy, Check } from "lucide-react";
import { useState } from "react";

export default function ASNAPIPage() {
  const [copied, setCopied] = useState(false);
  const basePath = process.env.NEXT_PUBLIC_BASE_PATH || "/ip-address-database";

  const copyToClipboard = async (text: string) => {
    try {
      await navigator.clipboard.writeText(text);
      setCopied(true);
      setTimeout(() => setCopied(false), 2000);
    } catch (err) {
      console.error("Failed to copy:", err);
    }
  };

  const endpoints = [
    {
      method: "GET",
      path: `${basePath}/data/asn.json`,
      description: "Get list of all ASNs with organization details",
      example: `{
  "total_asns": 84756,
  "total_networks": 1304915,
  "asns": [
    {
      "asn": "12311",
      "country_code": "AU",
      "name": "GTELECOM-AS-AP",
      "org": "Gtelecom Pty Ltd",
      "network_count": 150
    }
  ],
  "updated_at": "2026-07-30T01:49:17"
}`,
    },
    {
      method: "GET",
      path: `${basePath}/data/asn/{countryCode}/get.json`,
      description: "Get all ASNs for a specific country",
      example: `[
  {
    "network": "1.0.4.0/22",
    "asn": "38803",
    "country_code": "AU",
    "name": "GTELECOM-AS-AP",
    "org": "Gtelecom Pty Ltd",
    "domain": "gtelecom.com.au"
  }
]`,
    },
    {
      method: "GET",
      path: `${basePath}/data/asn/{countryCode}/{asn}/get.json`,
      description: "Get detailed data for a specific ASN",
      example: `[
  {
    "network": "1.0.4.0/22",
    "asn": "38803",
    "country_code": "AU",
    "name": "GTELECOM-AS-AP",
    "org": "Gtelecom Pty Ltd",
    "domain": "gtelecom.com.au"
  }
]`,
    },
  ];

  return (
    <div className="space-y-6">
      <Link
        href="/docs"
        className="inline-flex items-center gap-2 text-[#6f8a7d] hover:text-[#c6d2ca] transition-colors font-mono text-sm"
      >
        <ArrowLeft size={16} />
        Back to Documentation
      </Link>

      <div className="space-y-3">
        <div className="flex items-center gap-3">
          <span className="text-xs font-mono font-bold text-[#5c8aff] tracking-widest uppercase bg-[rgba(92,138,255,.08)] px-3 py-1 rounded-md border border-[rgba(92,138,255,.1)]">
            API Reference
          </span>
        </div>
        <h1 className="text-3xl md:text-4xl font-bold font-mono text-[#f2fff8]">
          ASN API
        </h1>
        <p className="text-[#93a79d] font-mono text-lg max-w-2xl">
          Retrieve Autonomous System Number details with organization and domain
          information.
        </p>
      </div>

      <div className="space-y-4">
        {endpoints.map((endpoint, index) => (
          <div
            key={index}
            className="bg-[rgba(92,138,255,.03)] border border-[rgba(92,138,255,.08)] rounded-xl p-6"
          >
            <div className="flex items-center gap-3 mb-3">
              <span className="text-xs font-mono font-bold text-[#5c8aff] bg-[rgba(92,138,255,.08)] px-2 py-1 rounded border border-[rgba(92,138,255,.1)]">
                {endpoint.method}
              </span>
              <code className="font-mono text-sm text-[#7fe9ab]">
                {endpoint.path}
              </code>
            </div>
            <p className="text-[#6f8a7d] font-mono text-sm">
              {endpoint.description}
            </p>
            <div className="relative mt-3">
              <pre className="bg-[#0a100d] border border-[rgba(34,229,122,.06)] rounded-lg p-4 overflow-x-auto font-mono text-sm text-[#7fe9ab]">
                {endpoint.example}
              </pre>
              <button
                onClick={() => copyToClipboard(endpoint.example)}
                className="absolute top-3 right-3 p-1.5 rounded-md bg-[rgba(34,229,122,.06)] hover:bg-[rgba(34,229,122,.1)] transition-colors"
              >
                {copied ? (
                  <Check size={14} className="text-[#22e57a]" />
                ) : (
                  <Copy size={14} className="text-[#6f8a7d]" />
                )}
              </button>
            </div>
          </div>
        ))}
      </div>
    </div>
  );
}
